static inline float gelu_f(float x)
{
    /* outside +-8 the function is exactly 0 or x to float precision */
    if (x <= -GELU_R) return 0.0f;
    if (x >=  GELU_R) return x;
    float t = (x + GELU_R) * GELU_SCALE;
    int   i = (int)t;
    float f = t - (float)i;
    return gelu_lut[i] + f * (gelu_lut[i + 1] - gelu_lut[i]);
}

/* dense: y[o] = W[o][.] . x[.] + b[o]   -- fp16 weights, fp32 math
 *
 * Weights are fp16 packed two-per-uint32. One VLDR pulls a word into an
 * FPU register; VCVTB unpacks the low half, VCVTT the high half. That is
 * ONE flash access per TWO weights.
 *
 * This matters because every weight is read exactly once per inference --
 * there is no reuse -- so the kernel is bound by flash transactions, not
 * by arithmetic. Halving the transactions is the whole point.
 *
 * The M4 (FPv4-SP) has NO fp16 arithmetic. fp16 is a storage format only.
 * VCVTB/VCVTT convert to fp32, which is EXACT (fp32 strictly contains
 * fp16 -- zero error, 1 cycle), and the MAC runs in fp32. The only error
 * is the storage rounding, measured at 5e-4 mm on contact location.
 *
 * Blocked over OUTPUTS 4 rows at a time, as in the fp32 path. */
#define ACT_LINEAR    0
#define ACT_GELU      1
#define ACT_RELU      2
#define ACT_SIGMOID   3
#define ACT_TANH      4
#define ACT_SOFTPLUS  5
#define ACT_ELU       6

typedef union { uint32_t u; float f; } w2_t;   /* two fp16 in one word */

#if defined(__ARM_ARCH) && defined(__ARM_FP)
/* hardware half<->single conversion (VCVTB/VCVTT), 1 cycle each */
static inline float lo16(float p)
{ float r; __asm("vcvtb.f32.f16 %0, %1" : "=t"(r) : "t"(p)); return r; }
static inline float hi16(float p)
{ float r; __asm("vcvtt.f32.f16 %0, %1" : "=t"(r) : "t"(p)); return r; }
#else
/* portable fallback: lets the golden-vector self-test build and run on a
 * host PC, so the port can be validated before it ever reaches hardware. */
static float h2f(uint16_t h)
{
    uint32_t s = (uint32_t)(h & 0x8000u) << 16;
    uint32_t e = (h >> 10) & 0x1Fu;
    uint32_t m =  h & 0x03FFu;
    w2_t o;
    if (e == 0u) {                       /* zero or subnormal */
        if (m == 0u) { o.u = s; return o.f; }
        while (!(m & 0x0400u)) { m <<= 1; --e; }
        ++e; m &= 0x03FFu;
    } else if (e == 31u) {               /* inf / nan */
        o.u = s | 0x7F800000u | (m << 13); return o.f;
    }
    o.u = s | ((e + 112u) << 23) | (m << 13);
    return o.f;
}
static inline float lo16(float p) { w2_t w; w.f = p; return h2f((uint16_t)(w.u & 0xFFFFu)); }
static inline float hi16(float p) { w2_t w; w.f = p; return h2f((uint16_t)(w.u >> 16)); }
#endif

static inline float activate(float v, int act)
{
    switch (act) {
        case ACT_GELU:     v = gelu_f(v); break;
        case ACT_SIGMOID:  v = 1.0f / (1.0f + expf(-v)); break;
    default: break;   /* ACT_LINEAR */
    }
    return v;
}

static void dense(const uint32_t *Wp, const float *bias, const float *x,
                  float *y, int n_in, int n_out, int act)
{
    const w2_t *W = (const w2_t *)Wp;
    const int nh = n_in >> 1;              /* packed words per row */
    const int o4 = n_out & ~3;             /* explicit bound: -Ofast range
                                            * analysis cannot prove
                                            * o <= n_out-4 is safe */
    int o = 0;
    for (; o < o4; o += 4) {
        const w2_t *r0 = W + (size_t)o * nh;
        const w2_t *r1 = r0 + nh;
        const w2_t *r2 = r1 + nh;
        const w2_t *r3 = r2 + nh;
        float a0 = 0.0f, a1 = 0.0f, a2 = 0.0f, a3 = 0.0f;
        for (int i = 0; i < nh; ++i) {
            const float x0 = x[2 * i], x1 = x[2 * i + 1];
            float p;
            p = r0[i].f; a0 += lo16(p) * x0; a0 += hi16(p) * x1;
            p = r1[i].f; a1 += lo16(p) * x0; a1 += hi16(p) * x1;
            p = r2[i].f; a2 += lo16(p) * x0; a2 += hi16(p) * x1;
            p = r3[i].f; a3 += lo16(p) * x0; a3 += hi16(p) * x1;
        }
        y[o    ] = activate(a0 + bias[o    ], act);
        y[o + 1] = activate(a1 + bias[o + 1], act);
        y[o + 2] = activate(a2 + bias[o + 2], act);
        y[o + 3] = activate(a3 + bias[o + 3], act);
    }
    for (; o < n_out; ++o) {              /* tail: heads have n_out = 1 or 3 */
        const w2_t *row = W + (size_t)o * nh;
        float a = 0.0f;
        for (int i = 0; i < nh; ++i) {
            const float p = row[i].f;
            a += lo16(p) * x[2 * i];
            a += hi16(p) * x[2 * i + 1];
        }
        y[o] = activate(a + bias[o], act);
    }
}

/* TactileFCNDecoder._decode:
 *   ax,ay,az = |ux|/a, |uy|/b, |uz|/c
 *   F = (ax**(2/eps2) + ay**(2/eps2))**(eps2/eps1) + az**(2/eps1)
 *   k = F**(-eps1/2);   u = k * u                                     */
static void normalize_u(float *u)
{
    float ax = fabsf(u[0]) / NN_SE_A;
    float ay = fabsf(u[1]) / NN_SE_B;
    float az = fabsf(u[2]) / NN_SE_C;
    /* eps1=1, eps2=0.5 exactly: 2/eps2=4, eps2/eps1=1/2, 2/eps1=2
     *   F = sqrt(ax^4 + ay^4) + az^2,   k = 1/sqrt(F).  No powf.  */
    float x2 = ax * ax, y2 = ay * ay;
    float F = sqrtf(x2 * x2 + y2 * y2) + az * az;
    float k = 1.0f / sqrtf(F);
    /* No F=0 guard, matching TactileFCNDecoder._decode. F is zero only if
     * the direction head emits exactly (0,0,0). Built with -Ofast, which
     * implies -ffinite-math-only, the compiler would delete such a guard
     * anyway. */
    u[0] *= k; u[1] *= k; u[2] *= k;
}

#define NN_SCRATCH 64
static float buf_a[NN_SCRATCH], buf_b[NN_SCRATCH], buf_z[NN_SCRATCH];

/* TactileRegressor.forward = decoder(encoder(x)) */
void nn_forward_raw(const float *in, nn_output_t *out)
{
    /* encoder:  256->64->64 */
    dense(w_encoder_0, b_encoder_0, in, buf_a, 256, 64, ACT_GELU);
    dense(w_encoder_1, b_encoder_1, buf_a, buf_b, 64, 64, ACT_GELU);

    /* trunk:  64->64->64 */
    dense(w_trunk_0, b_trunk_0, buf_b, buf_a, 64, 64, ACT_GELU);
    dense(w_trunk_1, b_trunk_1, buf_a, buf_z, 64, 64, ACT_LINEAR);

    /* flag:  64->64->1 */
    dense(w_flag_0, b_flag_0, buf_z, buf_a, 64, 64, ACT_GELU);
    dense(w_flag_1, b_flag_1, buf_a, buf_b, 64, 1, ACT_SIGMOID);

    out->contact_prob = buf_b[0];   /* sigmoid applied inside the layer */

    /* force:  64->64->3 */
    dense(w_force_0, b_force_0, buf_z, buf_a, 64, 64, ACT_GELU);
    dense(w_force_1, b_force_1, buf_a, out->F, 64, 3, ACT_LINEAR);

    /* dir:  64->64->3 */
    dense(w_dir_0, b_dir_0, buf_z, buf_a, 64, 64, ACT_GELU);
    dense(w_dir_1, b_dir_1, buf_a, out->u, 64, 3, ACT_LINEAR);

    normalize_u(out->u);
}

/* --- history ring buffer --- */
static float ring[NN_HISTORY][NN_N_TAXEL];
static int   head = 0, fill = 0;

void nn_reset(void) { memset(ring, 0, sizeof ring); head = 0; fill = 0; }

void nn_push(const float *taxels)
{
    memcpy(ring[head], taxels, NN_N_TAXEL * sizeof(float));
    head = (head + 1) % NN_HISTORY;
    if (fill < NN_HISTORY) ++fill;
}

int nn_infer(nn_output_t *out)
{
    static float in[NN_IN_CHAN];
    const float inv = 1.0f / NN_X_MAX;
    if (fill < NN_HISTORY) return 0;
    for (int t = 0; t < NN_HISTORY; ++t) {
        const float *s = ring[(head + t) % NN_HISTORY];  /* t = 0 -> oldest */
        float *d = &in[t * NN_N_TAXEL];                  /* TIME-MAJOR      */
        for (int c = 0; c < NN_N_TAXEL; ++c) d[c] = s[c] * inv;
    }
    nn_forward_raw(in, out);
    return 1;
}
